<template>
  <div class="data-screen">
    <TechBackground />

    <!-- 省份下钻过渡蒙层 -->
    <div class="province-drill-overlay" v-if="isDrilling" :class="{ 'show': isDrilling }">
      <div class="drill-content">
        <div class="drill-province-name">{{ currentProvince }}</div>
        <dv-decoration-9 class="drill-decoration" :color="['#00d4ff', '#00ffff']" />
        <div class="drill-loading">
          <dv-loading color="#00d4ff">数据加载中...</dv-loading>
        </div>
      </div>
    </div>

    <dv-border-box-13 class="screen-border">
      <header class="header">
        <div class="title-box">
          <dv-decoration-8 class="title-decoration" />
           <div class="title">链家网租房可视化大屏</div>
          <dv-decoration-8 :reverse="true" class="title-decoration" />
        </div>
        <div class="header-right">
          <button class="btn-predict" @click="goPredict">租金预测</button>
          <div class="user-info">
            <span class="username">{{ username }}</span>
            <button class="btn-logout" @click="handleLogout">退出</button>
          </div>
          <div class="time-display">{{ currentTime }}</div>
        </div>
      </header>

      <div class="main-content">
        <!-- 左侧面板 -->
        <div class="left-panel">
          <div class="map-main-box">
              <div class="map-container">
                <div class="hex-icons-wrapper">
                  <div class="hex-item">
                    <div class="hex-icon-box">
                      <img src="@/assets/icons/城市.png" alt="城市" class="hex-img" />
                    </div>
                    <div class="hex-data">
                      <span class="data-value">{{ homeData.top_city.name || '暂无数据' }}</span>
                      <span class="data-label">最多城市</span>
                    </div>
                  </div>

                  <div class="hex-item">
                    <div class="hex-icon-box">
                      <img src="@/assets/icons/户型.png" alt="户型" class="hex-img" />
                    </div>
                    <div class="hex-data">
                      <span class="data-value">{{ homeData.top_type.name || '暂无数据' }}</span>
                      <span class="data-label">最多户型</span>
                    </div>
                  </div>

                  <div class="hex-item">
                    <div class="hex-icon-box">
                      <img src="@/assets/icons/价格.png" alt="价格" class="hex-img" />
                    </div>
                    <div class="hex-data">
                      <span class="data-value">¥{{ homeData.avg_price || '0.00' }}</span>
                      <span class="data-label">平均价格</span>
                    </div>
                  </div>

                  <div class="hex-item">
                    <div class="hex-icon-box">
                      <img src="@/assets/icons/区域排序.png" alt="地区" class="hex-img" />
                    </div>
                    <div class="hex-data">
                      <span class="data-value">{{ homeData.top_district.name || '暂无数据' }}</span>
                      <span class="data-label">最多地区</span>
                    </div>
                  </div>
                </div>

                <div class="map-chart" ref="mapChart"></div>
              </div>
          </div>

          <div class="hot-buildings-box">
