                  <span class="ph-icon">
                    <svg t="1778900506830" class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="26107" width="24" height="20"><path d="M118.153846 526.178462c-7.876923 0-15.753846-3.150769-22.055384-8.664616-12.603077-11.815385-12.603077-32.295385-0.787693-44.898461L433.230769 120.516923c21.267692-22.055385 48.836923-33.870769 78.769231-33.870769s57.501538 11.815385 78.769231 33.870769l337.92 352.886154c11.815385 12.603077 11.815385 32.295385-0.787693 44.898461-12.603077 11.815385-32.295385 11.815385-44.898461-0.787692L545.083077 163.84C536.418462 154.387692 524.603077 149.661538 512 149.661538s-24.418462 4.726154-33.083077 14.178462L140.996923 516.726154c-6.301538 6.301538-14.178462 9.452308-22.843077 9.452308z" fill="#7ab8f6" p-id="26108"></path><path d="M827.076923 937.353846H196.923077c-8.664615 0-16.541538-3.150769-22.055385-9.452308-6.301538-6.301538-9.452308-14.178462-9.452307-22.055384V412.750769c0-17.329231 14.178462-31.507692 31.507692-31.507692s31.507692 14.178462 31.507692 31.507692V874.338462h567.138462V412.750769c0-17.329231 14.178462-31.507692 31.507692-31.507692s31.507692 14.178462 31.507692 31.507692V905.846154c0 17.329231-14.178462 31.507692-31.507692 31.507692z" fill="#7ab8f6" p-id="26109"></path><path d="M433.230769 577.378462h157.538462V905.846154H433.230769z" fill="#7ab8f6" p-id="26110"></path><path d="M590.769231 937.353846H433.230769c-17.329231 0-31.507692-14.178462-31.507692-31.507692V577.378462c0-17.329231 14.178462-31.507692 31.507692-31.507693h157.538462c17.329231 0 31.507692 14.178462 31.507692 31.507693V905.846154c0 17.329231-14.178462 31.507692-31.507692 31.507692z m-126.030769-63.015384h94.523076V608.886154H464.738462V874.338462zM827.076923 326.892308c22.055385 0 39.384615 17.329231 39.384615 39.384615 0-22.055385 17.329231-39.384615 39.384616-39.384615-22.055385 0-39.384615-17.329231-39.384616-39.384616 0 22.055385-17.329231 39.384615-39.384615 39.384616z" fill="#7ab8f6" p-id="26111"></path><pat