7ab8f6" p-id="26114"></path></svg>
                  </span>
                  <span class="ph-title">城 市 房 源 数 量 T O P 10</span>
                 </div>
                <div class="ph-corner"></div>
              </div>
              <div class="box-content chart-content">
                <div ref="cityHouseCountChart" class="chart-container"
                     @mouseenter="handleCityHouseCountEnter"
                     @mouseleave="handleCityHouseCountLeave"></div>
              </div>
          </div>
        </div>
      </div>
    </dv-border-box-13>
  </div>
</template>

<script>
import * as echarts from 'echarts';
import 'echarts-gl';
import 'echarts-wordcloud';
import TechBackground from '@/components/TechBackground.vue';
import request from '@/utils/request';

export default {
  name: 'Home',
  components: { TechBackground },
  data() {
    return {
      currentTime: '',
      mapChart: null,
      priceChart: null,
      homeData: {
        top_city: {},
        top_type: {},
        avg_price: 0,
        top_district: {},
        province_rank: {}
      },
      top10Buildings: [],
      priceDistribution: {
        price_ranges: [],
        zhengzu: [],
        hezu: []
      },
      cityRentRank: [],
      rentRankScrollTimer: null,
      isHoveringRentRank: false,
      cityRentTrend: {
        cities: [],
        整租均价: [],
        合租均价: []
      },
      houseTypeDistribution: {
        house_types: [],
        counts: [],
        percentages: [],
        total_count: 0
      },

      isDrilling: false,
      currentProvince: '',
      scrollTimer: null,
      isHoveringTable: false,
      priceDistScrollTimer: null,
      priceDistStartIndex: 0,
      rentTrendChart: null,
      houseTypePieChart: null,
      houseTypeHighlightTimer: null,
      houseTypeIsHovering: false,
     rentTypeData: {
        total_count: 0,
        rent_types: []
      },
      rentTypeIsHovering: false,
      username: localStorage.getItem('username') || '用户',
      featuredHouses: [],
      rentTypeHighlightTimer: null,
      featuredHousesScrollTimer: null,
      isHoveringFeaturedHouses: false,
      rentTrendStartIndex: 0,
      rentTrendScrollTimer: null,
      communityWordCloud: {
        total_communities: 0,
        total_words: 0,
        word_cloud: []
      },
      wordCloudChart: null,
      wordCloudAnimationTimer: null,
      cityHouseCountTop10: [],
      cityHouseCountScrollTimer: null,
      isHoveringCityHouseCount: false,
    }
  },

  mounted() {
    this.updateTime();
    setInterval(this.updateTime, 1000);
    this.$nextTick(() => {
      this.fetchHomeData();
      this.fetchTop10Buildings();
      this.fetchPriceDistribution();
      this.fetchCityRentRank();
      this.fetchCityRentTrend();
      this.fetchHouseTypeDistribution();
      this.fetchRentTypeAnalysis();
      this.fetchFeaturedHouses();
      this.fetchCommunityWordCloud();
      this.fetchCityHouseCountTop10();
    });

  },

  methods: {
    handleLogout() {
      if (confirm('确定要退出登录吗?')) {
        localStorage.removeItem('token');
        localStorage.removeItem('user_id');
        localStorage.removeItem('username');
        this.$router.push('/login');
      }
    },
    goPredict() {
      this.$router.push('/predict');
    },

    calculatePriceWidth(price) {
      const maxWidth = 100;
      const width = Math.min((price / 5000) * maxWidth, maxWidth);
      return width + '%';
    },

    updateTime() {
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      const day = String(now.getDate()).padStart(2, '0');
      const hours = String(now.getHours()).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const seconds = String(now.getSeconds()).padStart(2, '0');
      this.currentTime = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    },

    async fetchHomeData() {
      try {
        const res = await request.get('/analysis/api/home-data/');
        if (res.data && !res.data.error) {
          this.homeData = res.data;
          this.init3DMap();
        }
      } catch (err) {
        console.error('首页数据加载失败:', err);
      }
    },
    async fetchTop10Buildings() {
      try {
        const res = await request.get('/analysis/api/top10-buildings/');
        if (res.data && !res.data.error) {
          this.top10Buildings = res.data;
          this.$nextTick(() => {
            this.startSeamlessScroll();
          });
        }
      } catch (err) {
        console.error('热门楼盘数据加载失败:', err);
      }
    },
    async fetchPriceDistribution() {
      try {
        const res = await request.get('/analysis/api/price-distribution/');
        if (res.data && !res.data.error) {
          this.priceDistribution = res.data;
          this.initPriceChart();
        }
      } catch (err) {
        console.error('价格区间分布数据加载失败:', err);
      }
    },
    async fetchCityRentRank() {
      try {
        const res = await request.get('/analysis/api/city-rent-rank/');
        if (res.data && !res.data.error) {
          this.cityRentRank = res.data;
          this.$nextTick(() => {
            this.startRentRankScroll();
          });
        }
      } catch (err) {
        console.error('城市租金排行榜数据加载失败:', err);
      }
    },
    async fetchCityRentTrend() {
  try {
    const res = await request.get('/analysis/api/city-rent-trend/');
    if (res.data && !res.data.error) {
      this.cityRentTrend = res.data;
      this.$nextTick(() => {
        this.initRentTrendChart();
      });
    }
  } catch (err) {
    console.error('城市租金趋势数据加载失败:', err);
  }
},
    async fetchHouseTypeDistribution() {
  try {
    const res = await request.get('/analysis/api/house-type-distribution/');
    if (res.data && !res.data.error) {
      this.houseTypeDistribution = res.data;
      this.$nextTick(() => {
        this.initHouseTypePieChart();
      });
    }
  } catch (err) {
    console.error('户型分布数据加载失败:', err);
  }
},
    async fetchRentTypeAnalysis() {
  try {
    const res = await request.get('/analysis/api/rent-type-analysis/');
    if (res.data && !res.data.error) {
      this.rentTypeData = {
        total_count: res.data.total_count,
        rent_types: res.data.rent_types.filter(item =>
          item.rent_type !== '不限' && item.rent_type !== '方式'
        )
      };
      this.$nextTick(() => {
        this.initRentTypeChart();
      });
    }
  } catch (err) {
    console.error('租赁方式分析数据加载失败:', err);
  }
},

    async fetchFeaturedHouses() {
  try {
    const res = await request.get('/analysis/api/featured-houses/');
    if (res.data && !res.data.error) {
      this.featuredHouses = res.data.slice(0, 20);
      this.$nextTick(() => {
        this.startFeaturedHousesScroll();
      });
    }
  } catch (err) {
    console.error('必看好房数据加载失败:', err);
  }
},

    async fetchCommunityWordCloud() {
  try {
    const res = await request.get('/analysis/api/community-wordcloud/');
    if (res.data && !res.data.error) {
      this.communityWordCloud = res.data;
      this.$nextTick(() => {
        this.initWordCloudChart();
      });
    }
  } catch (err) {
    console.error('楼盘词云数据加载失败:', err);
  }
},

    async fetchCityHouseCountTop10() {
  try {
    const res = await request.get('/analysis/api/city-house-count-top10/');
    if (res.data && !res.data.error) {
      this.cityHouseCountTop10 = res.data.cities;
      this.cityHouseCountStartIndex = 0;
      this.$nextTick(() => {
        this.initCityHouseCountChart();
        this.startCityHouseCountScroll();
      });
    }
  } catch (err) {
    console.error('城市房源数量TOP 10数据加载失败:', err);
  }
},

    initCityHouseCountChart() {
  const dom = this.$refs.cityHouseCountChart;
  if (!dom || this.cityHouseCountTop10.length === 0) return;

  if (this.cityHouseCountChart) {
    this.cityHouseCountChart.dispose();
  }

  this.cityHouseCountChart = echarts.init(dom);

  const sorted = [...this.cityHouseCountTop10].sort((a, b) => b.house_count - a.house_count);
  this.cityHouseCountTop10 = sorted;

  const displayCount = Math.min(4, sorted.length);
  const displayData = sorted.slice(this.cityHouseCountStartIndex, this.cityHouseCountStartIndex + displayCount);

  const cities = displayData.map(item => item.city);
  const counts = displayData.map(item => item.house_count);

  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'none' },
      backgroundColor: 'rgba(0, 20, 40, 0.9)',
      borderColor: '#33cccc',
      textStyle: { color: '#c7eaff', fontSize: 13 },
      formatter: function(params) {
        const item = params[0];
        return item.name + '：' + item.value + ' 套';
      }
    },
    grid: {
      left: '3%',
      right: '15%',
      bottom: '30%',
      top: '1%',
      containLabel: true
    },
    xAxis: {
      type: 'value',
      axisLine: {
        lineStyle: {
          color: 'rgba(51, 204, 204, 0.3)'
        }
      },
      axisLabel: {
        color: '#c7eaff',
        fontSize: 11
      },
      splitLine: {
        lineStyle: {
          color: 'rgba(51, 204, 204, 0.1)'
        }
      }
    },
    yAxis: {
      type: 'category',
      data: cities,
      inverse: true,
      axisLine: {
        lineStyle: {
          color: 'rgba(51, 204, 204, 0.3)'
        }
      },
      axisLabel: {
        color: '#c7eaff',
        fontSize: 12,
        fontWeight: 'bold'
      }
    },
    series: [
      {
        type: 'bar',
        data: counts,
        barWidth: '45%',
        itemStyle: {
          color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
            { offset: 0, color: '#1a8a8a' },
            { offset: 1, color: '#33cccc' }
          ]),
          borderRadius: [0, 4, 4, 0]
        },
        label: {
          show: true,
          position: 'right',
          color: '#33cccc',
          fontSize: 12,
          fontWeight: 'bold'
        },
        animationType: 'expansion',
        animationEasing: 'cubicOut',
        animationDelay: function (idx) {
          return idx * 100;
        }
      }
    ]
  };

  this.cityHouseCountChart.setOption(option);

  window.addEventListener('resize', () => {
    if (this.cityHouseCountChart) {
      this.cityHouseCountChart.resize();
    }
  });
},
    startCityHouseCountScroll() {
  if (this.cityHouseCountScrollTimer) return;

  this.cityHouseCountScrollTimer = setInterval(() => {
    if (this.isHoveringCityHouseCount) return;

    this.cityHouseCountStartIndex++;

    if (this.cityHouseCountStartIndex >= this.cityHouseCountTop10.length - 3) {
      this.cityHouseCountStartIndex = 0;
    }

    this.initCityHouseCountChart();
  }, 2500);
},
    handleFeaturedHousesEnter() {
      this.isHoveringFeaturedHouses = true;
      if (this.featuredHousesScrollTimer) {
        clearInterval(this.featuredHousesScrollTimer);
        this.featuredHousesScrollTimer = null;
      }
    },
    handleFeaturedHousesLeave() {
      this.isHoveringFeaturedHouses = false;
      this.startFeaturedHousesScroll();
    },
    startFeaturedHousesScroll() {
      if (this.featuredHousesScrollTimer) return;

      const container = this.$refs.featuredHousesTableBody;
      if (!container) return;

      this.featuredHousesScrollTimer = setInterval(() => {
        const scrollHeight = container.scrollHeight;
        const scrollTop = container.scrollTop;
        const clientHeight = container.clientHeight;

        if (scrollTop >= scrollHeight / 2) {
          container.scrollTop = scrollTop - scrollHeight / 2;
        } else {
          container.scrollTop += 1;
        }
      }, 50);
    },
    handleRentRankEnter() {
      this.isHoveringRentRank = true;
      if (this.rentRankScrollTimer) {
        clearInterval(this.rentRankScrollTimer);
        this.rentRankScrollTimer = null;
      }
    },
    handleRentRankLeave() {
      this.isHoveringRentRank = false;
      this.startRentRankScroll();
    },
    handleCityHouseCountEnter() {
      this.isHoveringCityHouseCount = true;
      if (this.cityHouseCountScrollTimer) {
        clearInterval(this.cityHouseCountScrollTimer);
        this.cityHouseCountScrollTimer = null;
      }
    },
    handleCityHouseCountLeave() {
      this.isHoveringCityHouseCount = false;
      this.startCityHouseCountScroll();
    },
    initRentTypeChart() {
  const dom = this.$refs.rentTypeChart;
  if (!dom) return;
  const myChart = echarts.init(dom);

  const rentTypes = this.rentTypeData.rent_types;
  const totalCount = this.rentTypeData.total_count;

  const pieData = rentTypes.map((item, index) => ({
    name: item.rent_type,
    value: item.count,
    percentage: item.percentage
  }));

  const option = {
    tooltip: {
      trigger: 'item',
      backgroundColor: 'rgba(10, 25, 41, 0.95)',
      borderColor: '#00d4ff',
      borderWidth: 1,
      textStyle: { color: '#fff' },
      formatter: params => {
        return `${params.name}<br/>数量：${params.value}套<br/>占比：${params.data.percentage}%`;
      }
    },
    legend: {
      orient: 'vertical',
      left: '0.5%',
      top: '20%',
      textStyle: { color: '#c7eaff', fontSize: 11 },
      itemWidth: 15,
      itemHeight: 10,
      formatter: (name) => {
        const item = rentTypes.find(r => r.rent_type === name);
        return item ? `${name}  ${item.count}套  ${item.percentage}%` : name;
      }
    },

    graphic: [
      {
        type: 'text',
        right: '5%',
        top: '20%',
        style: {
          text: `总计 ${totalCount} 套`,
          fontSize: 16,
          fontWeight: 'bold',
          fill: '#00d4ff',
          textAlign: 'center'
        }
      },
      {
        type: 'line',
        right: '2%',
        top: '28%',
        style: {
          stroke: 'rgba(0, 212, 255, 0.3)',
          lineWidth: 1,
          width: 120
        }
      },
      ],
    series: [
      {
        name: '租赁方式',
        type: 'pie',
        radius: ['30%', '40%'],
        center: ['50%', '26%'],
        avoidLabelOverlap: false,
        itemStyle: {
          borderRadius: 5,
          borderColor: '#0a1929',
          borderWidth: 2
        },
        label: {
          show: false
        },
        emphasis: {
          scaleSize: 8,
          label: {
            show: true,
            fontSize: 14,
            fontWeight: 'bold',
            color: '#fff'
          }
        },
        labelLine: {
          show: false
        },
        animationType: 'scale',
        animationEasing: 'elasticOut',
        animationDelay: function (idx) {
          return Math.random() * 200;
        },
        data: pieData.map((item, index) => ({
          value: item.value,
          name: item.name,
          percentage: item.percentage,
          itemStyle: {
            color: ['#00d4ff', '#00c9a7', '#42c2ff', '#00ffff'][index % 4]
          }
        }))
      }
    ]
  };

  myChart.setOption(option);

  let currentIndex = -1;
  const dataLength = pieData.length;

  if (this.rentTypeHighlightTimer) clearInterval(this.rentTypeHighlightTimer);
  this.rentTypeHighlightTimer = setInterval(() => {
    if (this.rentTypeIsHovering) return;

    myChart.dispatchAction({
      type: 'downplay',
      seriesIndex: 0
    });

    currentIndex = (currentIndex + 1) % dataLength;

    myChart.dispatchAction({
      type: 'highlight',
      seriesIndex: 0,
      dataIndex: currentIndex
    });
  }, 1500);

  dom.addEventListener('mouseenter', () => {
    this.rentTypeIsHovering = true;
  });
  dom.addEventListener('mouseleave', () => {
    this.rentTypeIsHovering = false;
  });

  window.addEventListener('resize', () => {
    myChart.resize();
  });
},
    startRentRankScroll() {
      if (this.rentRankScrollTimer) return;

      const container = this.$refs.rentRankTableBody;
      if (!container) return;

      this.rentRankScrollTimer = setInterval(() => {
        const scrollHeight = container.scrollHeight;
        const scrollTop = container.scrollTop;
        const clientHeight = container.clientHeight;

        if (scrollTop >= scrollHeight / 2) {
          container.scrollTop = scrollTop - scrollHeight / 2;
        } else {
          container.scrollTop += 1;
        }
      }, 50);
    },

    handleTableEnter() {
      this.isHoveringTable = true;
      if (this.scrollTimer) {
        clearInterval(this.scrollTimer);
        this.scrollTimer = null;
      }
    },

    handleTableLeave() {
      this.isHoveringTable = false;
      this.startSeamlessScroll();
    },

    startSeamlessScroll() {
      if (this.scrollTimer) return;

      const container = this.$refs.top10TableBody;
      if (!container) return;

      this.scrollTimer = setInterval(() => {
        const scrollHeight = container.scrollHeight;
        const scrollTop = container.scrollTop;
        const clientHeight = container.clientHeight;

        if (scrollTop >= scrollHeight / 2) {
          container.scrollTop = scrollTop - scrollHeight / 2;
        } else {
          container.scrollTop += 1;
        }
      }, 50);
    },

    initPriceChart() {
      const dom = this.$refs.priceChart;
      if (!dom) return;
      this.priceChart = echarts.init(dom);
      const tooltipEl = this.$refs.priceTooltip;

      const showCount = 4;
      this.priceDistStartIndex = 0;

      const maxPrice = Math.max(...this.priceDistribution.zhengzu, ...this.priceDistribution.hezu);
      const yMax = Math.ceil(maxPrice / 1000) * 1000;

      const updateChart = () => {
        const allData = this.priceDistribution.price_ranges;
        let currentData;

        if (this.priceDistStartIndex <= allData.length - showCount) {
          currentData = allData.slice(this.priceDistStartIndex, this.priceDistStartIndex + showCount);
        } else {
          const remaining = allData.length - this.priceDistStartIndex;
          const needFromStart = showCount - remaining;
          currentData = [...allData.slice(this.priceDistStartIndex), ...allData.slice(0, needFromStart)];
        }

        const zhengzuData = [];
        const hezuData = [];
        currentData.forEach(range => {
          const idx = this.priceDistribution.price_ranges.indexOf(range);
          zhengzuData.push(this.priceDistribution.zhengzu[idx] || 0);
          hezuData.push(this.priceDistribution.hezu[idx] || 0);
        });

        this.priceChart.setOption({
          tooltip: { show: false },
          legend: {
            data: ['整租', '合租'],
            top: 5,
    textStyle: { color: '#c7eaff', fontSize: 13 },
    itemWidth: 20,
    itemHeight: 8
  },
          grid: {
            left: '12%',
            right: '5%',
            top: '20%',
            bottom: '15%'
          },
          xAxis: {
            type: 'category',
            data: currentData,
            axisLine: { lineStyle: { color: 'rgba(0, 150, 255, 0.3)' } },
            axisLabel: {
              color: '#c7eaff',
              fontSize: 10,
              interval: 0
            },
            axisTick: { show: false }
          },
          yAxis: {
            type: 'value',
            min: 0,
            max: yMax,
            axisLine: { show: false },
            axisLabel: { color: '#c7eaff', fontSize: 10 },
            splitLine: { lineStyle: { color: 'rgba(0, 150, 255, 0.15)' } }
          },
          series: [
            {
              name: '整租',
              type: 'bar',
              data: zhengzuData,
              barWidth: '30%',
              itemStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
                  { offset: 0, color: '#42c2ff' },
                  { offset: 1, color: 'rgba(66, 194, 255, 0.3)' }
                ])
              }
            },
            {
              name: '合租',
              type: 'bar',
              data: hezuData,
              barWidth: '30%',
              itemStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
                  { offset: 0, color: '#00c9a7' },
                  { offset: 1, color: 'rgba(0, 201, 167, 0.3)' }
                ])
              }
            }
          ]
        });

        this.priceDistStartIndex++;
        if (this.priceDistStartIndex >= allData.length) this.priceDistStartIndex = 0;
      };

      updateChart();

      if (this.priceDistScrollTimer) clearInterval(this.priceDistScrollTimer);
      this.priceDistScrollTimer = setInterval(updateChart, 2000);

      let hoveredIndex = -1;
      this.priceChart.getZr().on('mousemove', () => {
        if (this.priceDistScrollTimer) { clearInterval(this.priceDistScrollTimer); this.priceDistScrollTimer = null; }
      });

      this.priceChart.on('mouseover', (params) => {
        if (params.componentType !== 'series') return;
        const idx = params.dataIndex;
        hoveredIndex = idx;
        const option = this.priceChart.getOption();
        const names = option.legend[0].data;
        let html = '<div style="font-weight:bold;margin-bottom:4px;">' + params.name + '</div>';
        names.forEach((name, i) => {
          const val = option.series[i].data[idx];
          html += '<div>' + name + '：' + val + '套</div>';
        });
        tooltipEl.innerHTML = html;
        tooltipEl.style.display = 'block';
      });
      this.priceChart.on('globalout', () => {
        hoveredIndex = -1;
        tooltipEl.style.display = 'none';
        if (!this.priceDistScrollTimer) this.priceDistScrollTimer = setInterval(updateChart, 2000);
      });

      dom.addEventListener('mousemove', (e) => {
        if (tooltipEl.style.display === 'block') {
          const rect = dom.getBoundingClientRect();
          const tooltipH = tooltipEl.offsetHeight || 60;
          const tooltipW = tooltipEl.offsetWidth || 160;
          let left = e.clientX - rect.left + 15;
          let top = e.clientY - rect.top - tooltipH - 10;
          if (left + tooltipW > rect.width) left = e.clientX - rect.left - tooltipW - 15;
          if (top < 0) top = e.clientY - rect.top + 15;
          tooltipEl.style.left = left + 'px';
          tooltipEl.style.top = top + 'px';
        }
      });

      window.addEventListener('resize', () => {
        this.priceChart.resize();
      });
    },
    init3DMap() {
      if (!this.$refs.mapChart) return;
      this.mapChart = echarts.init(this.$refs.mapChart);

      const url = 'https://geo.datav.aliyun.com/areas_v3/bound/100000_full.json';

      fetch(url).then(res => res.json()).then(geoJson => {
        echarts.registerMap('china', geoJson);

        const provinces = geoJson.features.map(feature => {
          const name = feature.properties.name;
          let lon = 0, lat = 0, count = 0;
          const coords = feature.geometry.coordinates;

          coords.forEach(poly => {
            poly.forEach(ring => {
              ring.forEach(pt => {
                lon += pt[0];
                lat += pt[1];
                count++;
              });
            });
          });

          return {
            name: name,
            value: [lon / count, lat / count]
          };
        });

        const option = {
          tooltip: {
            show: true,
            trigger: 'item',
            backgroundColor: 'rgba(10, 25, 41, 0.95)',
            borderColor: '#00d4ff',
            borderWidth: 1,
            padding: [10, 14],
            textStyle: { color: '#fff', fontSize: 13 },
            formatter: (params) => {
              if (!params.name || params.seriesType !== 'map3D') return '';
              const name = params.name;
              const data = this.homeData.province_rank[name] || { rank: '-', sales: '-' };

              return `
                <div style="min-width: 130px;">
                  <div style="margin-bottom: 6px; display: flex; justify-content: space-between;">
                    <span style="color: rgba(255,255,255,0.6); font-size: 12px;">地区</span>
                    <span style="color: #00d4ff; font-weight: bold; font-size: 14px;">${name}</span>
                  </div>
                  <div style="margin-bottom: 6px; display: flex; justify-content: space-between;">
                    <span style="color: rgba(255,255,255,0.6); font-size: 12px;">排名</span>
                    <span style="color: #00ffff; font-weight: bold; font-size: 14px;">${data.rank}</span>
                  </div>
                  <div style="display: flex; justify-content: space-between;">
                    <span style="color: rgba(255,255,255,0.6); font-size: 12px;">租房数量</span>
                    <span style="color: #00ffff; font-weight: bold; font-size: 14px;">${data.sales}</span>
                  </div>
                </div>
              `;
            }
          },
          series: [{
            type: 'map3D',
            map: 'china',
            roam: true,
            boxHeight: 8,
            itemStyle: {
              color: '#1a3c5e',
              borderWidth: 1,
              borderColor: '#00d4ff'
            },
            emphasis: {
              itemStyle: { color: '#11b4da' },
              label: {
                show: true,
                textStyle: { color: '#ffffff', fontSize: 14 }
              }
            },
            label: { show: false },
            shading: 'lambert',
            light: {
              main: { intensity: 1.2, shadow: false, alpha: 50, beta: 10 },
              ambient: { intensity: 0.6 }
            },
            viewControl: {
              distance: 80,
              alpha: 50,
              beta: 0,
              autoRotate: false,
              center: [-15, 5, -5]
            },
            regions: []
          }]
        };

        this.mapChart.setOption(option);

        this.mapChart.on('click', (params) => {
          if (params.seriesType === 'map3D' && params.name && !this.isDrilling) {
            this.provinceDrillDown(params.name);
          }
        });
      }).catch(err => {
        console.error('地图加载失败:', err);
      });

      window.addEventListener('resize', () => {
        this.mapChart.resize();
      });
    },

    provinceDrillDown(provinceName) {
      this.isDrilling = true;
      this.currentProvince = provinceName;

      this.highlightProvince(provinceName);

      setTimeout(() => {
        this.$router.push({
          path: '/city-detail',
          query: { province: provinceName }
        });
      }, 2000);
