    initWordCloudChart() {
  const dom = this.$refs.wordCloudChart;
  if (!dom) return;

  if (this.wordCloudChart) {
    this.wordCloudChart.dispose();
  }

  this.wordCloudChart = echarts.init(dom);

  const wordCloudData = this.communityWordCloud.word_cloud;

  if (!wordCloudData || wordCloudData.length === 0) {
    console.warn('词云数据为空');
    return;
  }

  const colors = ['#33cccc', '#33b8cc', '#33a4cc', '#3d94cb'];

  const totalCount = wordCloudData.length;

  let groups = [];
  if (totalCount <= 30) {
    const groupSize = Math.ceil(totalCount / 2);
    groups = [
      wordCloudData.slice(0, groupSize),
      wordCloudData.slice(groupSize)
    ];
  } else {
    const groupSize = Math.ceil(totalCount / 3);
    groups = [
      wordCloudData.slice(0, groupSize),
      wordCloudData.slice(groupSize, groupSize * 2),
      wordCloudData.slice(groupSize * 2)
    ];
  }
  const shapes = ['circle', 'cardioid', 'diamond', 'triangle-forward', 'triangle', 'star'];
  const sizeRanges = [[12, 32], [10, 28], [10, 24]];
  const displayDurations = [4000, 4000, 3500];

  const createWordCloudOption = (groupData, shape, sizeRange) => ({
    tooltip: {
      show: true,
      backgroundColor: 'rgba(10, 25, 41, 0.95)',
      borderColor: '#33cccc',
      borderWidth: 1,
      textStyle: { color: '#fff' },
      formatter: (params) => {
        return `${params.name}<br/>出现次数: ${params.value}次`;
      }
    },
    series: [{
      type: 'wordCloud',
      shape: shape,
      left: 'center',
      top: 'center',
      width: '70%',
      height: '60%',
      right: null,
      bottom: null,
      sizeRange: sizeRange,
      rotationRange: [-45, 45],
      rotationStep: 15,
      gridSize: 6,
      drawOutOfBound: false,
      layoutAnimation: true,
      textStyle: {
        fontFamily: 'Microsoft YaHei',
        fontWeight: 'bold',
        color: function () {
          return colors[Math.floor(Math.random() * colors.length)];
        }
      },
      emphasis: {
        focus: 'self',
        textStyle: {
          shadowBlur: 10,
          shadowColor: '#33cccc',
          color: '#ffffff'
        }
      },
      data: groupData.map(item => ({
        name: item.name,
        value: item.value
      }))
    }]
  });

  let currentGroup = 0;
  let animationTimer = null;
  let isRunning = true;

  const playGroup = (groupIndex) => {
    if (!this.wordCloudChart || !isRunning) return;

    const groupData = groups[groupIndex];
    const shape = shapes[groupIndex % shapes.length];
    const sizeRange = sizeRanges[groupIndex % sizeRanges.length];

    this.wordCloudChart.clear();
    this.wordCloudChart.setOption(createWordCloudOption(groupData, shape, sizeRange));

    if (animationTimer) clearTimeout(animationTimer);

    animationTimer = setTimeout(() => {
      if (this.wordCloudChart && isRunning) {
        this.wordCloudChart.clear();

        setTimeout(() => {
          currentGroup = (currentGroup + 1) % groups.length;
          playGroup(currentGroup);
        }, 600);
      }
    }, displayDurations[groupIndex % displayDurations.length]);
  };

  playGroup(0);

  dom.addEventListener('mouseenter', () => {
    isRunning = false;
    if (animationTimer) {
      clearTimeout(animationTimer);
    }
  });

  dom.addEventListener('mouseleave', () => {
    isRunning = true;
    playGroup(currentGroup);
  });

  window.addEventListener('resize', () => {
    if (this.wordCloudChart) {
      this.wordCloudChart.resize();
    }
  });
},

  },
   beforeUnmount() {
    if (this.scrollTimer) clearInterval(this.scrollTimer);
    if (this.rentRankScrollTimer) clearInterval(this.rentRankScrollTimer);
    if (this.priceDistScrollTimer) clearInterval(this.priceDistScrollTimer);
    if (this.houseTypeHighlightTimer) clearInterval(this.houseTypeHighlightTimer);
    if (this.rentTypeHighlightTimer) clearInterval(this.rentTypeHighlightTimer);
    if (this.wordCloudAnimationTimer) clearInterval(this.wordCloudAnimationTimer);
    if (this.featuredHousesScrollTimer) clearInterval(this.featuredHousesScrollTimer);
